const v = SugarCube.State.variables;
const keys = Object.keys(v).filter(k => /harbor|captur|owner/i.test(k)).slice(0,40);
const out = {};
keys.forEach(k => out[k] = v[k]);
return JSON.stringify(out);

const divs = [...document.querySelectorAll('div')].filter(d => d.textContent && /^[\s\S]{0,5}(Cash on the Wheels|Gather the Materials|Funny Papers|The Long Count)/i.test(d.textContent.trim()) && d.textContent.length < 40);
divs.forEach(d => { const r = d.getBoundingClientRect(); if(r.height > 20 && r.height < 70) d.click(); });
return divs.length;

